  /* ── Names: letters, spaces and periods, first and last in full, in one alphabet ── */
  function titleCase(v) { return acClean(v).replace(/(^|[\s'’.])(\p{L})/gu, function (m, sep, ch) { return sep + ch.toLocaleUpperCase(); }); }
